const incorporados={"pdf":"","trabalhador":"","nucleo":""};
const bytes=b=>Uint8Array.from(atob(b),c=>c.charCodeAt(0));
const blob=(b,t)=>URL.createObjectURL(new Blob([bytes(b)],{type:t}));
const trabalhador=URL.createObjectURL(new Blob([bytes(incorporados.nucleo),'\n;self.TesseractCore=TesseractCore;\n',"const porBase64=\"\";const buscar=self.fetch.bind(self);self.fetch=(entrada,opcoes)=>{const url=typeof entrada==='string'?entrada:entrada.url;if(url==='local:/por.traineddata.gz')return Promise.resolve(new Response(Uint8Array.from(atob(porBase64),c=>c.charCodeAt(0))));return buscar(entrada,opcoes)};",'\n',bytes(incorporados.trabalhador)],{type:'text/javascript'}));
window.__pdfLocal={pdf:blob(incorporados.pdf,'text/javascript'),trabalhador,nucleo:'incorporado.js'};
